nsform:translate(-50%,-50%) scale(.08);opacity:0}.btn-ripple.show{animation:login-ripple .56s cubic-bezier(.23,1,.32,1) forwards}html[data-theme="dark"] .btn-ripple{background:radial-gradient(circle,rgba(255,255,255,.44) 0,rgba(255,255,255,.26) 36%,rgba(255,255,255,.1) 60%,rgba(255,255,255,0) 76%)}@keyframes login-ripple{0%{transform:translate(-50%,-50%) scale(.08);opacity:.76}58%{opacity:.42}100%{transform:translate(-50%,-50%) scale(1);opacity:0}}.err{width:250px;min-height:19px;margin:10px auto 0;color:#c65763;font-size:13px;line-height:1.5;text-align:center}
