<div class="container" id="container"><h1>访问验证</h1><div class="sub">请输入访问密码以继续</div><form class="form" id="login-form"><input type="password" id="pw" placeholder="访问密码" autocomplete="current-password"><button class="btn-login" id="btn" type="submit"><span class="btn-label">进入</span><span class="btn-ripple" aria-hidden="true"></span></button><div class="err" id="err" aria-live="polite"></div></form></div>
<ul class="bg-squares" aria-hidden="true"><li></li><li></li><li></li><li></li><li></li><li></li><li></li><li></li><li></li><li></li></ul><div id="handoff"></div>
<script>
const container=document.getElementById('container'),form=document.getElementById('login-form'),pw=document.getElementById('pw'),btn=document.getElementById('btn'),err=document.getElementById('err'),handoff=document.getElementById('handoff'),btnLabel=btn.querySelector('.btn-label'),ripple=btn.querySelector('.btn-ripple');let busy=false;function triggerRipple(event){if(busy)return;const rect=btn.getBoundingClientRect(),point=event.touches&&event.touches[0]?event.touches[0]:event,x=typeof point.clientX==='number'?point.clientX-rect.left:rect.width/2,y=typeof point.clientY==='number'?point.clientY-rect.top:rect.height/2,px=Math.max(0,Math.min(rect.width,x)),py=Math.max(0,Math.min(rect.height,y)),maxX=Math.max(px,rect.width-px),maxY=Math.max(py,rect.height-py),size=2*Math.sqrt(maxX*maxX+maxY*maxY);ripple.style.left=px+'px';ripple.style.top=py+'px';ripple.style.width=size+'px';ripple.style.height=size+'px';ripple.classList.remove('show');void ripple.offsetWidth;ripple.classList.add('show')}function pressButton(event){if(busy)return;btn.classList.add('is-pressed');triggerRipple(event)}function releaseButton(){btn.classList.remove('is-pressed')}if(window.PointerEvent){btn.addEventListener('pointerdown',pressButton);btn.addEventListener('pointerup',releaseButton);btn.addEventListener('pointercancel',releaseButton);btn.addEventListener('pointerleave',releaseButton)}else{btn.addEventListener('touchstart',pressButton,false);btn.addEventListener('touchend',releaseButton,false);btn.addEventListener('touchcancel',releaseButton,false);btn.addEventListener('mousedown',pressButton,false);window.addEventListener('mouseup',releaseButton,false)}btn.addEventListener('keydown',function(event){if((event.key==='Enter'||event.key===' ')&&!event.repeat)pressButton(event)});btn.addEventListener('keyup',releaseButton);btn.addEventListener('blur',releaseButton);ripple.addEventListener('animationend',function(){ripple.classList.remove('show')});
async function go(){if(busy)return;err.textContent='';if(!pw.value){err.textContent='请输入访问密码';pw.focus();return}busy=true;btn.disabled=true;btnLabel.textContent='验证中…';try{const r=await fetch('/api/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({password:pw.value})});if(r.ok){container.classList.add('success');btnLabel.textContent='进入中…';await new Promise(x=>setTimeout(x,360));handoff.classList.add('show');await new Promise(x=>setTimeout(x,320));location.href='/';return}const d=await r.json().catch(()=>({}));err.textContent=d.error||'密码错误';pw.value='';pw.focus()}catch(e){err.textContent='连接失败，请稍后重试'}busy=false;btn.disabled=false;btnLabel.textContent='进入'}
form.addEventListener('submit',e=>{e.preventDefault();go()});pw.focus();
</script></body></html>
